import type {
  MigrationErrorCode,
  MigrationOperation,
  MigrationStatus,
} from './contract.js';

/**
 * Sanitized observability record for one invocation outcome.
 *
 * `reason` is generated by the runner from bounded vocabulary — never SQL, row
 * data, driver messages, credentials, or tokens — so the structured CloudWatch
 * line can explain a failure or a mismatch without leaking database detail.
 */
export interface MigrationReport {
  operation: MigrationOperation;
  status: MigrationStatus;
  error_code: MigrationErrorCode | null;
  run_id: string;
  commit_sha: string;
  applied: number;
  pending: number;
  reason: string;
}

export type MigrationReporter = (report: MigrationReport) => void;

export const logMigrationReport: MigrationReporter = (report) => {
  console.log(JSON.stringify({ event: 'auth_migration', ...report }));
};
